# Line 388: "      // TODO: 保存到数据库"
# Through line 417: "      });"

# We'll replace lines 388-417 (1-indexed) with the new code
# That's indices 387..416 (0-indexed)

start_idx = None
end_idx = None
for i, line in enumerate(lines):
    if '// TODO: 保存到数据库' in line:
        start_idx = i
    if start_idx is not None and "message: '标的列表持久化成功'" in line:
        # Find the closing  });
        for j in range(i, min(i+3, len(lines))):
            if lines[j].strip() == '});':
                end_idx = j
                break
        break

if start_idx is None or end_idx is None:
    print(f'ERROR: could not find target region. start={start_idx}, end={end_idx}')
    sys.exit(1)

print(f'Found target region: lines {start_idx+1}-{end_idx+1}')

